mapper.sql:
WHERE 1 = 1
AND (m.job_nm LIKE CONCAT('%', #{keyword}, '%') OR m.company_nm LIKE CONCAT('%', #{keyword}, '%') OR u.user_nickname LIKE CONCAT('%', #{keyword}, '%') OR m.seed_nickname LIKE CONCAT('%', #{keyword}, '%'))
AND m.is_seed_yn = #{isSeedYn}

mapper.select:
SELECT m.salary_submission_sq, m.user_sq, u.user_nickname, m.is_seed_yn, m.seed_nickname, m.employment_type, m.job_nm, m.career_bucket, m.region_nm, m.annual_salary, m.company_nm, m.salary_submission_is_deleted_yn AS is_deleted_yn, m.created_at_dtm FROM TBL_SALARY_SUBMISSION_M m LEFT JOIN TBL_USER_M u ON u.user_sq = m.user_sq
ORDER BY m.created_at_dtm ASC ORDER BY m.annual_salary DESC ORDER BY m.created_at_dtm DESC
LIMIT #{size} OFFSET #{offset}
